package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import org.json.*;
import org.junit.*;

public final class ProjectExactPatchTest {
    private JSONObject snapshot;
    @Before public void create()throws Exception{snapshot=new JSONObject().put("checkout",new JSONObject().put("id","11111111-1111-1111-1111-111111111111").put("projectId","22222222-2222-2222-2222-222222222222")).put("files",new JSONArray());file("src/a.js","export const amount = 40;\n");file("src/b.js","export const other = 2;\n");}
    private void file(String path,String content)throws Exception{snapshot.getJSONArray("files").put(new JSONObject().put("path",path).put("content",content).put("sha256",ProjectSources.sha256(content.getBytes(StandardCharsets.UTF_8))));}
    private JSONObject edit(String path,String old,String value)throws Exception{String content=ProjectSources.files(snapshot).get(path);return new JSONObject().put("path",path).put("expectedHash",ProjectSources.sha256(content.getBytes(StandardCharsets.UTF_8))).put("replacements",new JSONArray().put(new JSONObject().put("oldText",old).put("newText",value)));}
    @Test public void smallExactHunkCanEditLargeFileAndRetainsOriginalBeforeAfterBytes()throws Exception{String large="/*"+"padding ".repeat(12000)+"*/\nexport const large = 40;\n";file("large.js",large);JSONObject patch=ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("large.js","large = 40","large = 45"))).getJSONObject(0);assertEquals(large,patch.getString("beforeContent"));assertTrue(patch.getString("content").endsWith("large = 45;\n"));assertEquals(ProjectSources.sha256(patch.getString("content").getBytes(StandardCharsets.UTF_8)),patch.getString("afterHash"));assertEquals(2,patch.getJSONArray("changes").getJSONObject(0).getInt("line"));}
    @Test public void entireMultiFileProposalFailsBeforeAnyEffectWhenLaterHunkIsMissing()throws Exception{assertThrows(SecurityException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("src/a.js","amount = 40","amount = 45")).put(edit("src/b.js","not in file","changed"))));assertEquals("export const amount = 40;\n",ProjectSources.files(snapshot).get("src/a.js"));}
    @Test public void ambiguousAndWhitespaceDifferentOldTextAreNotGuessed()throws Exception{file("twice.txt","same\nsame\n");assertThrows(SecurityException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("twice.txt","same","other"))));assertThrows(SecurityException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("src/a.js","amount=40","amount = 45"))));}
    @Test public void createDeleteAndSourcePathQuotasArePreflighted()throws Exception{JSONArray edits=new JSONArray().put(new JSONObject().put("path","new.js").put("action","create").put("expectedHash","absent").put("content","export default 1;\n")).put(new JSONObject().put("path","src/b.js").put("action","delete").put("expectedHash",edit("src/b.js","2","3").getString("expectedHash")));JSONArray result=ProjectExactPatch.prepare(snapshot,edits);assertEquals(2,result.length());assertEquals("absent",result.getJSONObject(1).getString("afterHash"));assertThrows(IllegalArgumentException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(new JSONObject().put("path","node_modules/owned.js").put("action","create").put("expectedHash","absent").put("content","x"))));}
    @Test public void duplicatePathsAndBinaryOrInvalidUnicodeCannotBecomeTextEdits()throws Exception{JSONObject edit=edit("src/a.js","40","45");assertThrows(IllegalArgumentException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit).put(edit)));snapshot.getJSONArray("files").put(new JSONObject().put("path","blob.bin").put("binary",true).put("contentBase64","AAE="));assertThrows(IllegalArgumentException.class,()->ProjectExactPatch.prepare(snapshot,new JSONArray().put(new JSONObject().put("path","blob.bin").put("expectedHash",ProjectSources.sha256(new byte[]{0,1})).put("action","delete"))));assertThrows(Exception.class,()->ProjectExactPatch.encode("bad\ud800"));}
    @Test public void conditionalUndoRestoresExactOriginalBytesAndRejectsNewerWork()throws Exception{JSONArray prepared=ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("src/a.js","40","45")));JSONObject file=prepared.getJSONObject(0);JSONObject actual=new JSONObject().put("receiptReceived",true).put("status","completed").put("exitCode",0).put("allFilesApplied",true).put("files",new JSONArray().put(new JSONObject().put("path",file.getString("path")).put("afterHash",file.getString("afterHash")).put("state","applied")));snapshot.getJSONArray("files").getJSONObject(0).put("content",file.getString("content")).put("sha256",file.getString("afterHash"));JSONArray reverse=ProjectExactPatch.reverse(snapshot,prepared,actual,"33333333-3333-3333-3333-333333333333");assertEquals("export const amount = 40;\n",reverse.getJSONObject(0).getString("content"));snapshot.getJSONArray("files").getJSONObject(0).put("content","owner newer").put("sha256",ProjectSources.sha256("owner newer".getBytes(StandardCharsets.UTF_8)));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot,prepared,actual,"33333333-3333-3333-3333-333333333333"));}
    @Test public void partialOrUnknownReceiptIsNotAnUndoTicket()throws Exception{JSONArray prepared=ProjectExactPatch.prepare(snapshot,new JSONArray().put(edit("src/a.js","40","45")));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot,prepared,new JSONObject().put("receiptReceived",false).put("status","unknown"),"33333333-3333-3333-3333-333333333333"));}
}
